// Tests for core/sssp. Evidence label: unit tests only. Expected values come from tools/sssp_ref.py (brute force over all simple paths for the small
// graphs; heapq Dijkstra plus a pass over the tight edges for the max-size graphs and as a cross-check on the mid graphs). Every success test uses a
// scratch array of exactly 8n + 3m + 2 words (filled with garbage) and dist, count and parent arrays of exactly n entries pre-filled with sentinels.
// Tiny or null buffers appear only for NullArgument, TooLarge, ScratchTooSmall, BadNode and BadWeight failures and for empty graphs. No test asserts
// any scratch value after a call. The max-size cases are sampled patterns, not exhaustive, checked by digest, by closed form and by an independent
// certificate checker (feasible potential, tight predecessors, counts and parents recomputed with std::sort). Time is not measured.
